using KardashevAscent.Simulation.Solar;
using NUnit.Framework;

namespace KardashevAscent.Simulation.Tests.Solar
{
    /// <summary>f_spec table from docs/physics/notes/stellar_exoplanet.md, regenerated by prototypes/solar/spectral_match.py.</summary>
    public class SpectralMatchTests
    {
        [TestCase(CellMaterial.Silicon, 2600.0, 0.43)]
        [TestCase(CellMaterial.Silicon, 3000.0, 0.58)]
        [TestCase(CellMaterial.Silicon, 3500.0, 0.74)]
        [TestCase(CellMaterial.Silicon, 4500.0, 0.93)]
        [TestCase(CellMaterial.GaAs, 2600.0, 0.22)]
        [TestCase(CellMaterial.GaAs, 3500.0, 0.53)]
        [TestCase(CellMaterial.CdTe, 3000.0, 0.31)]
        [TestCase(CellMaterial.Germanium, 2600.0, 1.05)]
        [TestCase(CellMaterial.Germanium, 3500.0, 1.16)]
        [TestCase(CellMaterial.GaAs, 6500.0, 1.05)]
        public void FSpec_MatchesResearchTable(CellMaterial material, double temperature, double expected)
        {
            Assert.AreEqual(expected, SpectralMatch.FSpec(material, temperature), 0.006);
        }

        [TestCase(CellMaterial.Silicon)]
        [TestCase(CellMaterial.GaAs)]
        [TestCase(CellMaterial.Germanium)]
        public void FSpec_IsOneUnderTheSun(CellMaterial material)
        {
            Assert.AreEqual(1.0, SpectralMatch.FSpec(material, 5778.0), 0.003);
        }

        [Test]
        public void Efficiency_SiliconUnderSunLikeBlackbodyIsAbout30Percent()
        {
            Assert.AreEqual(0.297, SpectralMatch.DetailedBalanceEfficiency(CellMaterial.Silicon, 5778.0), 0.002);
        }

        [Test]
        public void Efficiency_ClampsOutsideTable()
        {
            Assert.AreEqual(SpectralMatch.DetailedBalanceEfficiency(CellMaterial.Silicon, 2300.0),
                            SpectralMatch.DetailedBalanceEfficiency(CellMaterial.Silicon, 1000.0));
            Assert.AreEqual(SpectralMatch.DetailedBalanceEfficiency(CellMaterial.Silicon, 7500.0),
                            SpectralMatch.DetailedBalanceEfficiency(CellMaterial.Silicon, 20000.0));
        }

        [TestCase(2566.0, CellMaterial.Germanium)]   // TRAPPIST-1
        [TestCase(2900.0, CellMaterial.Germanium)]   // Proxima Cen
        [TestCase(5778.0, CellMaterial.GaAs)]
        public void BestMaterial(double temperature, CellMaterial expected)
        {
            Assert.AreEqual(expected, SpectralMatch.BestMaterial(temperature));
        }

        [TestCase(0.67, 1850.5)]
        [TestCase(1.12, 1107.0)]
        [TestCase(1.42, 873.1)]
        [TestCase(1.50, 826.6)]
        public void CutoffWavelength(double bandgap, double expectedNm)
        {
            Assert.AreEqual(expectedNm, SpectralMatch.CutoffWavelengthNm(bandgap), 0.5);
        }

        [TestCase(2566.0, 1129.3)]
        [TestCase(4450.0, 651.2)]
        [TestCase(5772.0, 502.0)]
        public void WienPeak(double temperature, double expectedNm)
        {
            Assert.AreEqual(expectedNm, SpectralMatch.WienPeakNm(temperature), 0.5);
        }
    }
}
